/* G40-549 R-D — the live request's progress, as the Stage 1 step bar.
 *
 * Mirrors requestOrder.js's "Current Status" checklist exactly (order_state
 * and the itemPurchaseCondition / itemPickedUpCondition rules), so the bar
 * ticks at the same moments the checklist did:
 *   Accepted      aasm index >= 1 (accepted; a booked "scheduled" too)
 *   In progress   aasm index >= 2 (picked_up)
 *   Item purchased / Item picked up   index >= 3 (purchased), only on the
 *                 requests that showed that row (Delivery, Other, and a Mulch
 *                 Project that needs delivery)
 *   Completed     delivered
 */

export const ORDER_STATE = [
  "pending",
  "accepted",
  "picked_up",
  "purchased",
  "delivered",
];

const goodsRun = (r) =>
  r?.category_type === "Delivery" ||
  r?.category_type === "Other" ||
  (r?.category_type === "Yard Project" &&
    r?.sub_category_type === "Mulch Project" &&
    !!r?.delivery_needed);

/** "purchased" | "picked_up" | null: which third row the checklist showed. */
export function itemStep(request) {
  if (!goodsRun(request)) return null;
  return (request?.cost_of_goods || 0) > 0 ? "purchased" : "picked_up";
}

/* "scheduled" is a scheduled request a worker has accepted: the server
   stores that hire as "scheduled" with the worker's gopher_id (backend
   controllers/order/update.js), and the live screen already says "{name}
   accepted your scheduled request". So the bar stands where "accepted"
   does: Accepted done, In progress next. It had no entry here, so a booked
   scheduled order ticked nothing (audit E, found in passing 2). */
const STEP_STATE = { scheduled: "accepted" };

/** [{label, done, current}] for the step bar. */
export function liveSteps(request, aasmState) {
  const i = ORDER_STATE.indexOf(STEP_STATE[aasmState] || aasmState);
  const item = itemStep(request);
  const steps = [
    { label: "Accepted", done: i >= 1 },
    { label: "In progress", done: i >= 2 },
  ];
  if (item) {
    steps.push({
      label: item === "purchased" ? "Item purchased" : "Item picked up",
      done: i >= 3,
    });
  }
  steps.push({ label: "Completed", done: aasmState === "delivered" });
  const firstOpen = steps.findIndex((s) => !s.done);
  return steps.map((s, k) => ({ ...s, current: k === firstOpen }));
}
